"Der Bringtag zählt nicht, der Holtag zählt. Klicke im Kalender zuerst den Bringtag, dann den Holtag an.": "Dzień wpłaty się nie liczy, dzień wypłaty się liczy. W kalendarzu kliknij najpierw dzień wpłaty, potem dzień wypłaty.",
