"Endwert": "wartość końcowa",
"zum Vergleich:": "dla porównania:",
"Urnenmodelle (Ziehen von Kugeln)": "Modele urnowe (losowanie kul)",
"Aus einer Urne mit n nummerierten Kugeln werden k Kugeln gezogen. Zwei Fragen legen das Modell fest: Wird zurückgelegt? Zählt die Reihenfolge?": "Z urny z n ponumerowanymi kulami losuje się k kul. Dwa pytania określają model: czy kula wraca do urny? Czy kolejność ma znaczenie?",
"Beobachte: Die vier Kombinationen ergeben vier Zählformeln. Mit «Neue Ziehung» siehst du ein Beispiel; die Rechnung zeigt die Anzahl der Möglichkeiten und die Wahrscheinlichkeit.": "Zauważ: cztery kombinacje dają cztery wzory zliczające. Przyciskiem „Nowe losowanie” zobaczysz przykład; obliczenie pokazuje liczbę możliwości i prawdopodobieństwo.",
"Eine Variante erklären": "Wyjaśnij jeden wariant",
"Alle vier vergleichen": "Porównaj wszystkie cztery",
"Kugeln in der Urne n": "Kule w urnie n",
"Gezogene Kugeln k": "Wylosowane kule k",
"{0} <1>Mit Zurücklegen</1>": "{0} <1>Ze zwracaniem</1>",
"{0} <1>Mit Reihenfolge</1>": "{0} <1>Z kolejnością</1>",
"Neue Ziehung": "Nowe losowanie",
"Gezogene Kugeln bleiben draussen. Beim ersten Zug hat man n Möglichkeiten, beim zweiten n − {0}, … beim k-ten n − k + {1}. Die Reihenfolge zählt. Multiplikationsprinzip: n · (n − {2}) · … · (n − k + {3}) = n!/(n − k)!.": "Wylosowane kule zostają poza urną. W pierwszym losowaniu jest n możliwości, w drugim n − {0}, … w k-tym n − k + {1}. Kolejność ma znaczenie. Zasada mnożenia: n · (n − {2}) · … · (n − k + {3}) = n!/(n − k)!.",
"Alle {0} Möglichkeiten sind gleich wahrscheinlich.": "Wszystkie {0} możliwości są jednakowo prawdopodobne.",
"Urne mit {0} Kugeln, {1} werden gezogen": "Urna z {0} kulami, losuje się {1}",
"Urne mit {0} Kugeln, eine wird gezogen": "Urna z {0} kulami, losuje się jedną",
"zurücklegen": "zwrócić",
"Folge der gezogenen Kugeln (Reihenfolge zählt)": "Ciąg wylosowanych kul (kolejność ma znaczenie)",
"Menge der gezogenen Kugeln (Reihenfolge egal)": "Zbiór wylosowanych kul (kolejność nie ma znaczenia)",
"Variation ohne Wiederholung": "Wariacja bez powtórzeń",
"Variation mit Wiederholung": "Wariacja z powtórzeniami",
"Kombination ohne Wiederholung": "Kombinacja bez powtórzeń",
"Kombination mit Wiederholung": "Kombinacja z powtórzeniami",
"ohne Zurücklegen, mit Reihenfolge": "bez zwracania, z kolejnością",
"mit Zurücklegen, mit Reihenfolge": "ze zwracaniem, z kolejnością",
"ohne Zurücklegen, ohne Reihenfolge": "bez zwracania, bez kolejności",
"mit Zurücklegen, ohne Reihenfolge": "ze zwracaniem, bez kolejności",
"Anzahl Möglichkeiten:": "Liczba możliwości:",
"Wahrscheinlichkeit für das gezogene Ergebnis:": "Prawdopodobieństwo wylosowanego wyniku:",
"Jede gezogene Kugel wird zurückgelegt, darum hat man bei jedem der k Züge wieder n Möglichkeiten. Die Reihenfolge zählt: ({0}, {1}) und ({2}, {3}) sind verschieden. Multiplikationsprinzip: n · n · … · n mit k Faktoren.": "Każda wylosowana kula wraca do urny, więc w każdym z k losowań jest znów n możliwości. Kolejność ma znaczenie: ({0}, {1}) i ({2}, {3}) są różne. Zasada mnożenia: n · n · … · n z k czynnikami.",
"Es zählt nur, welche Kugeln gezogen wurden (wie bei einem Griff in die Urne). Jede Auswahl von k Kugeln lässt sich auf k! Arten anordnen. Darum teilt man die Zahl der Variationen n!/(n − k)! durch k!. Das ist der Binomialkoeffizient «n über k».": "Liczy się tylko to, które kule wylosowano (jak przy chwyceniu garści z urny). Każdy wybór k kul można ułożyć na k! sposobów. Dlatego liczbę wariacji n!/(n − k)! dzieli się przez k!. To jest współczynnik dwumianowy „n nad k”.",
"Die Kugeln werden zurückgelegt, aber nur die gezogene Menge zählt: Kugeln dürfen mehrfach vorkommen, die Reihenfolge nicht. Zählen mit Sternen und Strichen: k Kugeln («Sterne») und n − {0} Trennstriche zwischen den n Nummern ergeben n + k − {1} Plätze, auf denen man k für die Sterne wählt.": "Kule wracają do urny, ale liczy się tylko wylosowany zbiór: kule mogą się powtarzać, kolejność nie ma znaczenia. Liczenie metodą gwiazdek i kresek: k kul („gwiazdki”) i n − {0} kresek rozdzielających n numerów daje n + k − {1} miejsc, z których wybiera się k dla gwiazdek.",
"Die Möglichkeiten sind nicht gleich wahrscheinlich: Mengen mit verschiedenen Kugeln kommen häufiger vor.": "Możliwości nie są jednakowo prawdopodobne: zbiory z różnymi kulami zdarzają się częściej.",
"k = n: Alle Kugeln werden gezogen (Permutation).": "k = n: losuje się wszystkie kule (permutacja).",
"Ohne Zurücklegen: Jede Auswahl lässt sich auf k! Arten anordnen. Variationen = k! · Kombinationen:": "Bez zwracania: każdy wybór można ułożyć na k! sposobów. Wariacje = k! · kombinacje:",
"Mit Zurücklegen gibt es meistens mehr Möglichkeiten als ohne.": "Ze zwracaniem zwykle jest więcej możliwości niż bez zwracania.",
"Die vier Urnenmodelle im Vergleich: {0} Kugeln, {1} werden gezogen": "Cztery modele urnowe w porównaniu: {0} kul, losuje się {1}",
"mit Reihenfolge": "z kolejnością",
