"<0>Schritt {1}:</0> Durch {2} dividieren: zuerst {3} ausklammern, dann kürzen.": "<0>Krok {1}:</0> podzielić przez {2}: najpierw wyłączyć {3} przed nawias, potem skrócić.",
"<0>Schritt {1}:</0> Grenzwert {2} bilden: alle Summanden mit {3} fallen weg.": "<0>Krok {1}:</0> obliczyć granicę {2}: wszystkie składniki z {3} znikają.",
"Oben der Graph von f, unten der Graph der Ableitung f′. Ziehe den Punkt: Die Höhe des unteren Punktes ist die Steigung der Tangente oben.": "Na górze wykres f, na dole wykres pochodnej f′. Przeciągnij punkt: wysokość dolnego punktu to nachylenie stycznej na górze.",
"Wo f steigt, ist f′ positiv (grün), wo f fällt, ist f′ negativ (orange). Bei waagrechter Tangente ist f′ = {0}.": "Tam, gdzie f rośnie, f′ jest dodatnia (zielona); tam, gdzie f maleje, f′ jest ujemna (pomarańczowa). Przy poziomej stycznej f′ = {0}.",
