"Differenzenquotient und Grenzwert": "Iloraz różnicowy i granica",
"Bei dieser Funktion lässt sich der Differenzenquotient nicht zu einem Term vereinfachen, der sich durch {0} kürzen lässt. Die Tabelle zeigt, wohin die Differenzenquotienten streben. Die Ableitung berechnest du mit den Ableitungsregeln.": "W przypadku tej funkcji ilorazu różnicowego nie da się uprościć do wyrażenia, które można skrócić przez {0}. Tabela pokazuje, do czego dążą ilorazy różnicowe. Pochodną obliczasz według reguł różniczkowania.",
