"<0>Schritt {1}:</0> Hauptsatz: Obere Grenze einsetzen, untere Grenze einsetzen, subtrahieren.": "<0>Krok {1}:</0> Podstawowe twierdzenie: podstawić górną granicę, podstawić dolną granicę, odjąć.",
