"Für diese Funktion gibt es keine Stammfunktion in einfacher Form (z. B. {0} oder {1}). Das bestimmte Integral wird numerisch berechnet.": "Ta funkcja nie ma funkcji pierwotnej w prostej postaci (np. {0} lub {1}). Całka oznaczona jest obliczana numerycznie.",
"Für diese Funktion gibt es keine Stammfunktion in einfacher Form. Das Integral wird numerisch berechnet.": "Ta funkcja nie ma funkcji pierwotnej w prostej postaci. Całka jest obliczana numerycznie.",
