"Fläche zwischen {0} und der {1}-Achse": "Pole między {0} a osią {1}",
"<0>Schritt {1}:</0> Nullstellen von {2} im Intervall suchen ({3}).": "<0>Krok {1}:</0> Szukać miejsc zerowych {2} w przedziale ({3}).",
"Im Inneren des Intervalls gibt es keine Nullstelle, also wechselt das Vorzeichen nicht.": "Wewnątrz przedziału nie ma miejsca zerowego, więc znak się nie zmienia.",
"<0>Schritt {1}:</0> Das Intervall an diesen Stellen teilen und jedes Stück einzeln integrieren. Unterhalb der Achse (bzw. von {2}) ist das Integral negativ, die Fläche ist sein Betrag.": "<0>Krok {1}:</0> Podzielić przedział w tych punktach i scałkować każdy kawałek osobno. Pod osią (lub pod {2}) całka jest ujemna, pole jest jej wartością bezwzględną.",
"Stammfunktion von f": "Funkcja pierwotna f",
"Intervall": "Przedział",
"<0>Schritt {1}:</0> Die Teilflächen addieren.": "<0>Krok {1}:</0> Dodać pola cząstkowe.",
"Das Integral ohne Betrag würde die Teilflächen mit ihrem Vorzeichen verrechnen: {0}.": "Bez wartości bezwzględnej całka dodałaby pola cząstkowe z ich znakami: {0}.",
"Fläche zwischen {0} und {1}": "Pole między {0} a {1}",
"<0>Schritt {1}:</0> Schnittstellen von {2} und {3} im Intervall suchen ({4}).": "<0>Krok {1}:</0> Szukać punktów przecięcia {2} i {3} w przedziale ({4}).",
"Dreht man den Graphen von f um die x-Achse, entsteht ein Körper aus lauter dünnen Kreisscheiben. Jede Scheibe hat das Volumen π · {0}² · Δx.": "Gdy obrócimy wykres f wokół osi x, powstaje bryła złożona z wielu cienkich krążków. Każdy krążek ma objętość π · {0}² · Δx.",
"Erhöhe die Zahl der Scheiben: Die Summe der Scheibenvolumen nähert sich dem Volumen V = π ∫ f².": "Zwiększ liczbę krążków: suma objętości krążków zbliża się do objętości V = π ∫ f².",
"Anzahl Scheiben": "Liczba krążków",
