"Die Gerade {0}": "Prosta {0}",
"<0>Steigung</0> {1}: Wächst {2} um {3}, so ändert sich {4} um {5}.": "<0>Współczynnik kierunkowy</0> {1}: Jeśli {2} rośnie o {3}, to {4} zmienia się o {5}.",
"<0>y-Achsenabschnitt</0> {1}: Der Wert bei {2}.": "<0>Wyraz wolny</0> {1}: Wartość przy {2}.",
"<0>Nullstelle:</0> Hier ist {1}.": "<0>Miejsce zerowe:</0> Tutaj {1}.",
"Nullstelle {0}, also {1}": "Miejsce zerowe {0}, czyli {1}",
"<0>Steigungswinkel:</0> Die Gerade bildet mit der {1}-Achse den Winkel {2}.": "<0>Kąt nachylenia:</0> Prosta tworzy z osią {1} kąt {2}.",
"Die Steigung ist positiv: Die Gerade steigt.": "Współczynnik kierunkowy jest dodatni: prosta rośnie.",
"Die Steigung ist negativ: Die Gerade fällt.": "Współczynnik kierunkowy jest ujemny: prosta maleje.",
"Die Gerade verläuft parallel zur {0}-Achse und hat keine Nullstelle.": "Prosta biegnie równolegle do osi {0} i nie ma miejsca zerowego.",
"Die Steigung ist null: Die Gerade verläuft waagrecht.": "Współczynnik kierunkowy jest równy zero: prosta biegnie poziomo.",
"Die Gerade ist die {0}-Achse selbst: Jede Stelle ist eine Nullstelle.": "Prosta jest samą osią {0}: każdy punkt jest miejscem zerowym.",
"Jede Stelle ist Nullstelle": "Każdy punkt jest miejscem zerowym",
"Das ist keine lineare Funktion. Erlaubt ist m·x + q.": "To nie jest funkcja liniowa. Dozwolone jest m·x + q.",
"Eine Gerade ist durch zwei Punkte oder durch einen Punkt und die Steigung festgelegt. Aus Δy und Δx folgt m, dann folgt q aus einem Punkt.": "Prostą wyznaczają dwa punkty albo punkt i współczynnik kierunkowy. Z Δy i Δx wynika m, następnie q wynika z jednego punktu.",
"Ziehe die Punkte P und Q. Mit dem Punkt R kannst du die Parallele und die Senkrechte zur Geraden durch R zeigen.": "Przeciągnij punkty P i Q. Punktem R możesz pokazać prostą równoległą i prostopadłą do danej prostej przez R.",
