"<0>Schritt {1}:</0> Parallele Geraden haben dieselbe Steigung.": "<0>Krok {1}:</0> Proste równoległe mają ten sam współczynnik kierunkowy.",
"<0>Schritt {1}:</0> Punkt {2} einsetzen und {3} bestimmen.": "<0>Krok {1}:</0> Podstawić punkt {2} i wyznaczyć {3}.",
"<0>Schritt {1}:</0> Senkrechte Geraden haben Steigungen mit Produkt {2}.": "<0>Krok {1}:</0> Proste prostopadłe mają współczynniki kierunkowe o iloczynie {2}.",
"<0>Schritt {1}:</0> {2} verläuft waagrecht, also ist die Senkrechte eine senkrechte Gerade.": "<0>Krok {1}:</0> {2} biegnie poziomo, więc prostopadła jest prostą pionową.",
"Der Schnittpunkt zweier Geraden löst beide Gleichungen gleichzeitig. Die Tabelle zeigt, wo die y-Werte von f und g übereinstimmen.": "Punkt przecięcia dwóch prostych spełnia oba równania jednocześnie. Tabela pokazuje, gdzie wartości y funkcji f i g są równe.",
"Ziehe die Punkte auf der y-Achse, um q{0} und q{1} zu ändern. Sind die Steigungen gleich, gibt es keinen Schnittpunkt (parallel) oder unendlich viele (identisch).": "Przeciągnij punkty na osi y, aby zmienić q{0} i q{1}. Gdy współczynniki kierunkowe są równe, nie ma punktu przecięcia (proste równoległe) albo jest ich nieskończenie wiele (proste identyczne).",
