"<0>Schnittwinkel:</0> Der spitze Winkel {1} zwischen den Geraden folgt aus den Steigungen.": "<0>Kąt przecięcia:</0> Kąt ostry {1} między prostymi wynika ze współczynników kierunkowych.",
