"Umkehrfunktion von": "funkcja odwrotna do",
"Rechenweg: Wurzelfunktion": "Rozwiązanie: funkcja pierwiastkowa",
"Wurzelfunktion als Umkehrfunktion": "Funkcja pierwiastkowa jako funkcja odwrotna",
"<0>Umkehrung:</0> Die Wurzelfunktion macht das Potenzieren rückgängig. Aus {1} wird nach {2} aufgelöst (nur für {3}, damit die Zuordnung eindeutig ist), dann werden {4} und {5} vertauscht.": "<0>Odwracanie:</0> Funkcja pierwiastkowa cofa potęgowanie. Z {1} wyznaczamy {2} (tylko dla {3}, aby przyporządkowanie było jednoznaczne), potem zamieniamy {4} i {5}.",
"Der Graph der Umkehrfunktion ist das <0>Spiegelbild</0> des Graphen von {1} an der Winkelhalbierenden {2}: Jeder Punkt {3} wird zu {4}.": "Wykres funkcji odwrotnej jest <0>odbiciem</0> wykresu {1} względem prostej {2}: Każdy punkt {3} przechodzi w {4}.",
"<0>Definitions- und Wertebereich:</0> Eine gerade Wurzel aus einer negativen Zahl gibt es in {1} nicht; die Wurzel ist nie negativ.": "<0>Dziedzina i zbiór wartości:</0> Pierwiastek parzystego stopnia z liczby ujemnej nie istnieje w {1}; pierwiastek nigdy nie jest ujemny.",
"<0>Potenzschreibweise:</0> Die Wurzel ist eine Potenz mit dem Exponenten {1}, denn {2}.": "<0>Zapis potęgowy:</0> Pierwiastek jest potęgą o wykładniku {1}, ponieważ {2}.",
"<0>Beispiel</0> mit {1}: erst potenzieren, dann die Wurzel ziehen.": "<0>Przykład</0> z {1}: najpierw podnieść do potęgi, potem obliczyć pierwiastek.",
"{0} ist die Umkehrfunktion von {1} (für {2})": "{0} jest funkcją odwrotną do {1} (dla {2})",
"Umkehrfunktion:": "Funkcja odwrotna:",
